import type { PreSignUpTriggerHandler } from "aws-lambda";

/**
 * Owner-only sign up:
 * - No invites
 * - Stamp a custom attribute so we can pick it up later (e.g., in PostConfirmation)
 */
export const handler: PreSignUpTriggerHandler = async (event) => {
  // Only run for native sign-up
  if (event.triggerSource !== "PreSignUp_SignUp") return event;

  // Force everyone through this path to be Owner
  event.request.userAttributes["custom:role"] = "Owner";

  // You can also auto-confirm here if you want:
  // event.response.autoConfirmUser = true;

  return event;
};
